input.command:
cat > $TMPDIR/scan4.py <<'EOF'
import re, os, json
sites = json.load(open(os.path.join(os.environ["TMPDIR"],"sites.json")))
by_file = {}
for f, ln, txt in sites:
    by_file.setdefault(f, []).append((ln, txt))

save_pat = re.compile(r"^\s*(?:const\s+)?(?:struct\s+)?(\w+)?\s*\*?\s*(\w+)\s*=\s*(.+);")
interesting_save = re.compile(r"skb->data|skb_header_pointer|skb_(transport|network|mac)_header|skb_(tail|head)pointer|skb_(pull|push)_data|skb->head\b|skb_tail_pointer")
use_pat_tpl = r"\b{0}\b"

def analyze(path, ln, txt, src_lines):
    # window: 30 lines before, 15 after
    lo, hi = max(1, ln-30), ln+15
    window = [(n, src_lines[n-1]) for n in range(lo, min(hi, len(src_lines))+1)]
    ptrs = {}
    for n, t in window:
        m = re.match(r"^\s*(?:const\s+)?(?:unsigned\s+)?(?:struct\s+)?\w+\s*\*\s*(\w+)\s*=\s*([^;]+);", t)
        if m and interesting_save.search(m.group(2)):
            ptrs[m.group(1)] = (n, m.group(2).strip())
    hits = []
    for name,(sn, sv) in ptrs.items():
        for n, t in window:
            if n <= sn: continue
            if n <= ln and n >= sn and False: pass
            if re.search(r"\b"+re.escape(name)+r"\s*(->|\[|\)|,|\)|;|\s*==|\s*\+|\s*-)", t):
                # distinguish before free (ok) vs after free (bad)
                if n > ln:
                    hits.append((name, sn, sv, n, t.strip()))
                # if used between save and free only -> fine
    return ptrs, hits

results = []
for f, lst in by_file.items():
    try:
        src = open(f, errors="replace").read().splitlines()
    except Exception:
        continue
    for ln, txt in lst:
        ptrs, hits = analyze(f, ln, txt, src)
        if hits:
            results.append((f, ln, txt.strip(), hits))
print("candidate windows:", len(results))
for r in results:
    f, ln, txt, hits = r
    print(f"{f}:{ln}: {txt}")
    for h in hits:
        print(f"    ptr {h[0]} saved@{h[1]} = {h[2]!r} used@{h[3]}: {h[4]}")
json.dump(results, open(os.path.join(os.environ["TMPDIR"],"res2.json"),"w"))
EOF
python3 $TMPDIR/scan4.py 2>&1 | head -100

