cat > $TMPDIR/scan6.py <<'EOF'
import re, os, json
sites = json.load(open(os.path.join(os.environ["TMPDIR"],"sites.json")))
by_file = {}
for f, ln, txt in sites:
    by_file.setdefault(f, []).append((ln, txt))

interesting_save = re.compile(r"skb->data|skb_header_pointer|skb_(transport|network|mac)_header|skb_tail_pointer|skb_(pull|push)_data|skb->head\b")
save_re = re.compile(r"^\s*(?:const\s+)?(?:unsigned\s+)?(?:struct\s+)?[\w\d_]+\s*\**\s*(\w+)\s*=\s*([^;]+);")
free_call = re.compile(r"\b(kfree_skb|consume_skb|dev_kfree_skb_any|dev_kfree_skb_irq|napi_consume_skb|__kfree_skb|skb_unref)\s*\(")

def find_func_bounds(src, ln):
    # walk back to func start: line beginning with non-ws that ends with '{' or start of file; naive: find last line before ln matching r'^\w.*\(' at col 0
    start = 0
    for n in range(ln-1, 0, -1):
        t = src[n-1]
        if re.match(r'^[a-zA-Z_]', t) and (t.rstrip().endswith('{') or t.rstrip().endswith(')')):
            start = n
            break
    end = min(len(src), ln+80)
    return start, end

results = []
for f, lst in by_file.items():
    try:
        src = open(f, errors="replace").read().splitlines()
    except Exception:
        continue
    for ln, txt in lst:
        fs, fe = find_func_bounds(src, ln)
        if not fs: continue
        window = [(n, src[n-1]) for n in range(fs, min(fe, len(src))+1)]
        ptrs = {}
        for n, t in window:
            m = save_re.match(t)
            if m and interesting_save.search(m.group(2)):
                ptrs[m.group(1)] = (n, m.group(2).strip())
        for name,(sn, sv) in ptrs.items():
            uses_after = []
            for n, t in window:
                if n <= ln: continue
                if re.search(r"\b"+re.escape(name)+r"\b", t) and not re.search(r"\b"+re.escape(name)+r"\s*=", t):
                    uses_after.append((n, t.strip()))
            if uses_after and sn < ln:
                results.append((f, fs, fe, ln, txt.strip(), name, sn, sv, uses_after[:6]))
uniq = {}
for r in results:
    key = (r[0], r[3], r[5])
    if key not in uniq:
        uniq[key] = r
print("total:", len(uniq))
for r in sorted(uniq.values()):
    print(f"{r[0]}: func@{r[1]}-{r[2]} free@{r[3]}: {r[4]}")
    print(f"    ptr {r[5]} saved@{r[6]} = {r[7]!r}")
    for un, ut in r[8]:
        print(f"      used@{un}: {ut[:150]}")
json.dump([[r[0],r[1],r[2],r[3],r[4],r[5],r[6],r[7],r[8]] for r in uniq.values()], open(os.path.join(os.environ["TMPDIR"],"res3.json"),"w"))
EOF
python3 $TMPDIR/scan6.py 2>&1 | tail -80

