import re, os, json

saves = json.load(open(os.path.join(os.environ["TMPDIR"],"saves.json")))
by={}
for f,ln,var,expr in saves: by.setdefault(f,[]).append((ln,var,expr))

store_re = re.compile(r'^\s*([\w\>\.\[\]]+(?:\-\>|\.)[\w\[\]]+)\s*=\s*([^;]+);')
results=[]
for f, lst in by.items():
    try:
        src = open(f, errors="replace").read().splitlines()
    except Exception:
        continue
    for ln, var, expr in lst:
        # look ahead up to 60 lines for stores of var into struct fields, and for free calls, and for queue handoffs
        window = range(ln, min(ln+60, len(src))+1)
        free_after=None; handoff_after=None
        for n in window:
            t = src[n-1]
            if free_after is None and re.search(r'\b(kfree_skb|consume_skb|dev_kfree_skb|dev_kfree_skb_any|napi_consume_skb|skb_unref)\s*\(', t):
                free_after=n
            if handoff_after is None and re.search(r'\b(skb_queue_tail|skb_queue_head|sock_queue_rcv_skb|netif_rx|netif_receive_skb)\s*\(', t):
                handoff_after=n
        if free_after or handoff_after:
            results.append((f, ln, var, expr, free_after, handoff_after))
print("save-then-free/handoff pairs:", len(results))
for r_ in results:
    print(f"{r_[0]}:{r_[1]} var={r_[2]} = {r_[3][:50]!r} free@{r_[4]} handoff@{r_[5]}")
